-- Core school tenant controls. School administrators manage only their own school; Super Admin manages every school.
create or replace function public.is_assigned_teacher_for_subject_name(p_class uuid,p_subject_name text) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.class_subjects cs join public.school_subjects ss on ss.id=cs.subject_id where cs.class_id=p_class and cs.teacher_id=auth.uid() and cs.active and lower(ss.name)=lower(p_subject_name)); $$;
create or replace function public.is_teacher_for_subject_in_school(p_school uuid,p_subject_name text) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.class_subjects cs join public.school_classes c on c.id=cs.class_id join public.school_subjects ss on ss.id=cs.subject_id where c.school_id=p_school and cs.teacher_id=auth.uid() and cs.active and lower(ss.name)=lower(p_subject_name)); $$;

-- Replace broad core policies.
drop policy if exists "schools members read own" on public.schools;
drop policy if exists "school members read own" on public.school_members;
drop policy if exists "school classes read authorised" on public.school_classes;
drop policy if exists "class members read authorised" on public.class_members;
drop policy if exists "subjects authorised" on public.school_subjects;
drop policy if exists "class subjects authorised" on public.class_subjects;
drop policy if exists "class subjects strict" on public.class_subjects;
create policy "schools scoped read" on public.schools for select to authenticated using(public.is_super_admin() or public.is_school_member(id));
create policy "schools admin manage own" on public.schools for update to authenticated using(public.is_super_admin() or public.is_school_member(id,array['school_admin'])) with check(public.is_super_admin() or public.is_school_member(id,array['school_admin']));
create policy "school members scoped read" on public.school_members for select to authenticated using(public.is_super_admin() or user_id=auth.uid() or public.is_school_member(school_id));
create policy "school members admin manage" on public.school_members for all to authenticated using(public.is_super_admin() or public.is_school_member(school_id,array['school_admin'])) with check(public.is_super_admin() or public.is_school_member(school_id,array['school_admin']));
create policy "school classes scoped read" on public.school_classes for select to authenticated using(public.is_super_admin() or public.is_school_member(school_id));
create policy "school classes admin manage" on public.school_classes for all to authenticated using(public.is_super_admin() or public.is_school_member(school_id,array['school_admin'])) with check(public.is_super_admin() or public.is_school_member(school_id,array['school_admin']));
create policy "class members scoped read" on public.class_members for select to authenticated using(public.is_super_admin() or user_id=auth.uid() or exists(select 1 from public.school_classes c where c.id=class_id and(public.is_school_member(c.school_id,array['school_admin']) or public.is_class_teacher_for(c.id) or exists(select 1 from public.class_members mine where mine.class_id=c.id and mine.user_id=auth.uid() and mine.role='teacher'))));
create policy "class members admin manage" on public.class_members for all to authenticated using(public.is_super_admin() or exists(select 1 from public.school_classes c where c.id=class_id and public.is_school_member(c.school_id,array['school_admin']))) with check(public.is_super_admin() or exists(select 1 from public.school_classes c where c.id=class_id and public.is_school_member(c.school_id,array['school_admin'])));
create policy "school subjects scoped read" on public.school_subjects for select to authenticated using(public.is_super_admin() or public.is_school_member(school_id));
create policy "school subjects admin manage" on public.school_subjects for all to authenticated using(public.is_super_admin() or public.is_school_member(school_id,array['school_admin'])) with check(public.is_super_admin() or public.is_school_member(school_id,array['school_admin']));
create policy "class subjects scoped read" on public.class_subjects for select to authenticated using(public.is_super_admin() or exists(select 1 from public.school_classes c where c.id=class_id and(public.is_school_member(c.school_id) or teacher_id=auth.uid())));
create policy "class subjects admin manage" on public.class_subjects for all to authenticated using(public.is_super_admin() or exists(select 1 from public.school_classes c where c.id=class_id and public.is_school_member(c.school_id,array['school_admin']))) with check(public.is_super_admin() or exists(select 1 from public.school_classes c where c.id=class_id and public.is_school_member(c.school_id,array['school_admin'])));

-- Teacher question/CBT authoring is limited to allocated class + subject.
drop policy if exists "question banks authorised" on public.teacher_question_banks;
drop policy if exists "question items authorised" on public.teacher_question_items;
drop policy if exists "cbt exams authorised" on public.school_cbt_exams;
create policy "question banks scoped" on public.teacher_question_banks for all to authenticated using(public.is_super_admin() or public.is_school_member(school_id,array['school_admin']) or(public.is_teacher_for_subject_in_school(school_id,subject) and teacher_id=auth.uid())) with check(public.is_super_admin() or public.is_school_member(school_id,array['school_admin']) or(public.is_school_member(school_id,array['teacher']) and teacher_id=auth.uid()));
create policy "question items scoped" on public.teacher_question_items for all to authenticated using(exists(select 1 from public.teacher_question_banks b where b.id=bank_id and(public.is_super_admin() or public.is_school_member(b.school_id,array['school_admin']) or b.teacher_id=auth.uid()))) with check(exists(select 1 from public.teacher_question_banks b where b.id=bank_id and(public.is_super_admin() or public.is_school_member(b.school_id,array['school_admin']) or b.teacher_id=auth.uid())));
create policy "cbt exams scoped" on public.school_cbt_exams for all to authenticated using(public.is_super_admin() or public.is_school_member(school_id,array['school_admin']) or(teacher_id=auth.uid() and public.is_assigned_teacher_for_subject_name(class_id,subject))) with check(public.is_super_admin() or public.is_school_member(school_id,array['school_admin']) or(teacher_id=auth.uid() and public.is_assigned_teacher_for_subject_name(class_id,subject)));
